 void SelectAllEntries(object sender,KeyEventArgs e){if(e.Key!=Key.A||(Keyboard.Modifiers&ModifierKeys.Control)==0)return;foreach(Entry item in entries.Items)if(!entries.SelectedItems.Contains(item))entries.SelectedItems.Add(item);e.Handled=true;}
 void EnableReorder(){Point start=default;Entry? item=null;string[] selectedAtPress=[];entries.PreviewMouseLeftButtonDown+=(_,e)=>{start=e.GetPosition(entries);item=e.ClickCount==1?(ItemsControl.ContainerFromElement(entries,e.OriginalSource as DependencyObject) as ListViewItem)?.Content as Entry:null;selectedAtPress=item!=null&&entries.SelectedItems.Cast<Entry>().Any(x=>string.Equals(x.Path,item.Path,StringComparison.OrdinalIgnoreCase))?entries.SelectedItems.Cast<Entry>().Select(x=>x.Path).ToArray():[];};entries.PreviewMouseLeftButtonUp+=(_,_)=>{item=null;selectedAtPress=[];};entries.MouseLeave+=(_,_)=>item=null;entries.PreviewMouseMove+=(_,e)=>{if(item==null||e.LeftButton!=MouseButtonState.Pressed)return;var now=e.GetPosition(entries);if(Math.Abs(now.X-start.X)<SystemParameters.MinimumHorizontalDragDistance&&Math.Abs(now.Y-start.Y)<SystemParameters.MinimumVerticalDragDistance)return;var path=item.Path;item=null;var paths=selectedAtPress.Length>0?selectedAtPress:entries.SelectedItems.Cast<Entry>().Select(x=>x.Path).ToArray();if(!paths.Contains(path,StringComparer.OrdinalIgnoreCase))paths=[path];selectedAtPress=[];try{var data=ShellItems.CreateData(paths);data.SetData(ReorderFormat,new[]{Config.Id.ToString()}.Concat(paths).ToArray());DragDrop.DoDragDrop(entries,data,DragDropEffects.Move|DragDropEffects.Copy|DragDropEffects.Link);}catch(System.Runtime.InteropServices.COMException){}catch(InvalidOperationException){}catch(IOException){}};}
 internal void ReorderEntry(string path,string? before)=>ReorderEntries([path],before);
 internal void ReorderEntries(IReadOnlyList<string> paths,string? before){if(Config.Folder!=null)return;var movingSet=paths.ToHashSet(StringComparer.OrdinalIgnoreCase);if(movingSet.Count==0||(before!=null&&movingSet.Contains(before)))return;var moving=Config.Entries.Where(movingSet.Contains).ToArray();if(moving.Length==0)return;Config.Entries.RemoveAll(movingSet.Contains);var target=before==null?-1:Config.Entries.FindIndex(p=>string.Equals(p,before,StringComparison.OrdinalIgnoreCase));if(target<0)Config.Entries.AddRange(moving);else Config.Entries.InsertRange(target,moving);app.Save();Refresh();}
 void OnDrop(object s,DragEventArgs e){var payload=e.Data.GetDataPresent(ReorderFormat)?e.Data.GetData(ReorderFormat) as string[]:null;if(payload is {Length:>=2}&&Guid.TryParse(payload[0],out var sourceId)&&sourceId==Config.Id&&IsOwnReorder(e.Data)){var moving=payload.Skip(1).ToArray();var movingSet=moving.ToHashSet(StringComparer.OrdinalIgnoreCase);var target=ItemsControl.ContainerFromElement(entries,e.OriginalSource as DependencyObject) as ListViewItem;var targetPath=(target?.Content as Entry)?.Path;var before=targetPath;if(target!=null&&e.GetPosition(target).Y>target.ActualHeight/2){var index=Config.Entries.FindIndex(p=>string.Equals(p,targetPath,StringComparison.OrdinalIgnoreCase));before=index<0?null:Config.Entries.Skip(index+1).FirstOrDefault(p=>!movingSet.Contains(p));}ReorderEntries(moving,before);e.Handled=true;return;}var failures=ReceiveDrop(e.Data);if(failures.Count==0&&payload is {Length:>=2}&&Guid.TryParse(payload[0],out sourceId)&&sourceId!=Config.Id){var source=app.Windows.FirstOrDefault(w=>w.Config.Id==sourceId);if(source!=null&&source.Config.Folder==null){var moved=payload.Skip(1).ToHashSet(StringComparer.OrdinalIgnoreCase);source.Config.Entries.RemoveAll(moved.Contains);source.app.Save();source.app.RefreshDesktop();source.Refresh();}}if(failures.Count>0)MessageBox.Show(string.Join("\n",failures),"部分项目未收纳");e.Handled=true;}
internal IReadOnlyList<string> ReceiveDrop(System.Windows.IDataObject data){IReadOnlyList<string> paths;try{paths=ShellItems.Read(data);}catch(Exception ex){return [ex.Message];}var failures=new List<string>();foreach(var path in paths){try{if(Config.Folder==null){if(!ShellItems.Exists(path))throw new IOException("入口不存在");if(!Config.Entries.Contains(path,StringComparer.OrdinalIgnoreCase))Config.Entries.Add(path);}else{if(ShellItems.IsVirtual(path))throw new IOException("系统入口不能移动到映射文件夹。");FileActions.MoveInto(path,Config.Folder);}}catch(Exception ex){failures.Add(ShellItems.DisplayName(path)+"："+ex.Message);}}app.Save();app.RefreshDesktop();Refresh();return failures;}
 static void OpenEntry(string path){if(ShellItems.IsVirtual(path))Process.Start(new ProcessStartInfo("explorer.exe",path.StartsWith("shell:",StringComparison.OrdinalIgnoreCase)?path:"shell:"+path){UseShellExecute=true});else Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}
 void Try(Action action){try{action();}catch(Exception ex){MessageBox.Show(ex.Message,"操作失败");}}
 internal void DisposeAndClose(){closing=true;watcher?.Dispose();timer.Stop();frostTimer.Stop();frostImage.Source=null;BackgroundSampler.SetExcluded(this,false);Close();}
